    }

    .details p {
      margin: 0;
    }

    .details[hidden] {
      display: none;
    }

    .details p + p {
      margin-top: 0.85rem;
    }

    @media (max-width: 640px) {
      .shell {
        width: min(100% - 1rem, 920px);
        padding-top: 3.5rem;
      }

      .hero,
      .toggle,
      .details {
        padding-left: 1rem;
        padding-right: 1rem;
      }
    }

    @media (forced-colors: active) {
      :root {
        --bg: Canvas;
        --bg-elevated: Canvas;
        --panel: Canvas;
        --panel-strong: Canvas;
        --border: ButtonBorder;
        --border-strong: ButtonBorder;
        --text: CanvasText;
        --muted: CanvasText;
        --accent: LinkText;
        --accent-strong: LinkText;
        --focus: Highlight;
      }

      .hero,
      .example {
        forced-color-adjust: auto;
      }

      .skip-link:focus,
      .toggle:focus-visible {
        outline-color: Highlight;
        box-shadow: none;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#main">Skip to main content</a>
  <div id="app"></div>

  <script>
    const faqData = [
      {
        question: "Why do cats knead with their paws?",
        answer: [
          "Kneading is a comforting instinct that starts in kittenhood when cats press against their mother's belly to encourage milk flow. Adult cats often repeat the behavior when they feel safe, relaxed, or especially attached to a person.",
          "If your cat kneads you, it is usually a compliment."
        ]
      },
      {
        question: "Why do cats purr?",
        answer: [
          "Purring often signals contentment, but cats may also purr when they are nervous, in pain, or trying to self-soothe. The sound can be part comfort signal, part coping mechanism."
        ]
      },
      {
        question: "How much sleep do cats need?",
        answer: [
          "Most cats sleep between 12 and 16 hours a day, and some sleep even more. Their bursty hunting style means they conserve energy whenever they can."
        ]
      },
      {
        question: "Do cats need to go outside?",
        answer: [
          "No. Many cats live healthier, safer lives indoors with enough enrichment, vertical space, play, and windows to watch the world. If a cat goes outside, supervision or a secure enclosure is safer than free roaming."
        ]
      },
      {
        question: "Why do cats bring home toys or prey?",
        answer: [
          "Cats are natural hunters and may treat toys, bugs, or small prey as trophies, gifts, or practice targets. The behavior is instinctive, even if the delivery is less than glamorous."
        ]
      }
    ];

    function FAQItem({ question, answer, index }) {
      const contentId = `faq-answer-${index}`;
      return `
        <div class="example">
          <button
            class="toggle"
            type="button"
            aria-expanded="false"
            aria-controls="${contentId}"
          >
            <span class="question">${question}</span>
            <span class="chevron" aria-hidden="true"></span>
          </button>
          <div class="details" id="${contentId}" hidden>
            ${answer.map((paragraph) => `<p>${paragraph}</p>`).join("")}
          </div>
        </div>
      `;
    }

    function FAQPage() {
      return `
        <main id="main" class="shell">
          <section class="hero" aria-labelledby="faq-title">
            <p class="eyebrow">Frequently asked questions</p>
            <h1 id="faq-title">Cat FAQ</h1>
            <p class="intro">
              A calm, dark-themed guide to common cat behaviors. Click any question to expand its answer.
            </p>
          </section>
          <section class="faq-list" aria-label="Cat frequently asked questions">
            ${faqData.map((item, index) => FAQItem({ ...item, index })).join("")}
          </section>
        </main>
      `;
    }

    function renderApp() {
      document.getElementById("app").innerHTML = FAQPage();

      document.querySelectorAll(".example").forEach((item) => {
        const button = item.querySelector(".toggle");
        const panel = item.querySelector(".details");

        button.addEventListener("click", () => {
          const isOpen = button.getAttribute("aria-expanded") === "true";
          button.setAttribute("aria-expanded", String(!isOpen));
          panel.hidden = isOpen;
        });
      });
    }

    renderApp();
  </script>
