     function FAQItem({ question, answer, index }) {
       const contentId = `faq-answer-${index}`;
       return `
         <div class="example">
           <button
             class="toggle"
             type="button"
             aria-expanded="false"
             aria-controls="${contentId}"
           >
             <span class="question">${question}</span>
             <span class="chevron" aria-hidden="true"></span>
           </button>
           <div class="details" id="${contentId}" hidden>
             ${answer.map((paragraph) => `<p>${paragraph}</p>`).join("")}
           </div>
         </div>
       `;
     }

     function FAQPage() {
       return `
         <main id="main" class="shell">
           <section class="hero" aria-labelledby="faq-title">
             <p class="eyebrow">Frequently asked questions</p>
             <h1 id="faq-title">Cat FAQ</h1>
             <p class="intro">
               A calm, dark-themed guide to common cat behaviors. Click any question to expand its answer.
             </p>
           </section>
           <section class="faq-list" aria-label="Cat frequently asked questions">
             ${faqData.map((item, index) => FAQItem({ ...item, index })).join("")}
           </section>
         </main>
       `;
     }

     function renderApp() {
       document.getElementById("app").innerHTML = FAQPage();

       document.querySelectorAll(".example").forEach((item) => {
         const button = item.querySelector(".toggle");
         const panel = item.querySelector(".details");

         button.addEventListener("click", () => {
           const isOpen = button.getAttribute("aria-expanded") === "true";
           button.setAttribute("aria-expanded", String(!isOpen));
           panel.hidden = isOpen;
         });
       });
     }

     renderApp();
   </script>
